import { column, Schema, Table } from "@powersync/web";
import { rejectedWriteTable } from "@samesight/supabase";

// Generated by samesight from samesight.policy.ts. Do not edit: change the policy and run
// `samesight generate`. One table per synced Postgres table, as the sync streams send it.

const Tenant = new Table({
  name: column.text,
  createdAt: column.text,
});

const Membership = new Table({
  userId: column.text,
  tenantId: column.text,
  role: column.text,
  displayName: column.text,
  createdAt: column.text,
});

const Site = new Table({
  tenantId: column.text,
  name: column.text,
  address: column.text,
  createdAt: column.text,
});

const Inspection = new Table({
  tenantId: column.text,
  siteId: column.text,
  assigneeId: column.text,
  title: column.text,
  status: column.text,
  // Not synced to VIEWER; always null on their devices.
  internalNotes: column.text,
  createdAt: column.text,
  updatedAt: column.text,
});

const Finding = new Table({
  tenantId: column.text,
  inspectionId: column.text,
  supersedesId: column.text,
  // Assigned by the server; null until the row has synced.
  seq: column.integer,
  body: column.text,
  severity: column.text,
  createdBy: column.text,
  createdAt: column.text,
});

const Photo = new Table({
  tenantId: column.text,
  inspectionId: column.text,
  findingId: column.text,
  storagePath: column.text,
  sha256: column.text,
  createdBy: column.text,
  createdAt: column.text,
});

// RejectedWrite is local-only: writes the server refused for good, kept and shown.
export const AppSchema = new Schema({
  Tenant,
  Membership,
  Site,
  Inspection,
  Finding,
  Photo,
  RejectedWrite: rejectedWriteTable,
});

export type Database = (typeof AppSchema)["types"];
export type TenantRecord = Database["Tenant"];
export type MembershipRecord = Database["Membership"];
export type SiteRecord = Database["Site"];
export type InspectionRecord = Database["Inspection"];
export type FindingRecord = Database["Finding"];
export type PhotoRecord = Database["Photo"];
